import java.util.*;

public class Main {
    static final int INF = 0x3f3f3f3f;

    // Flow graph arrays
    static int[] uu, vv, uv, cost, cost_, cc;
    static ArrayList<Integer>[] flowAdj;
    static int m_;

    // Dijkstra arrays
    static int[] pi, kk, bb;
    static int[] pq, iq;
    static int cnt;

    // Original graph adjacency
    static ArrayList<Integer>[] origAdj;

    // Priority queue methods
    static boolean LT(int u, int v) {
        return pi[u] < pi[v] || (pi[u] == pi[v] && kk[u] < kk[v]);
    }

    static int i2(int i) {
        int left = i * 2;
        if (left > cnt) return 0;
        int right = left + 1;
        if (right <= cnt && LT(pq[right], pq[left]))
            return right;
        return left;
    }

    static void pq_up(int u) {
        int i = iq[u];
        while (i > 1) {
            int j = i / 2;
            if (!LT(u, pq[j])) break;
            pq[i] = pq[j];
            iq[pq[j]] = i;
            i = j;
        }
        pq[i] = u;
        iq[u] = i;
    }

    static void pq_dn(int u) {
        int i = iq[u];
        while (true) {
            int j = i2(i);
            if (j == 0 || !LT(pq[j], u)) break;
            pq[i] = pq[j];
            iq[pq[j]] = i;
            i = j;
        }
        pq[i] = u;
        iq[u] = i;
    }

    static void pq_add(int u) {
        iq[u] = ++cnt;
        pq_up(u);
    }

    static int pq_remove_first() {
        int u = pq[1];
        int v = pq[cnt--];
        iq[v] = 1;
        pq[1] = v;
        pq_dn(v);
        return u;
    }

    // Add an edge to the flow network (directed with reverse edge)
    static void link(int u, int v, int cap, int cos) {
        int h = m_++;
        uu[h] = u;
        vv[h] = v;
        uv[h] = u ^ v;
        cost[h] = cos;
        cost_[h] = cos;
        cc[h << 1] = cap;
        cc[(h << 1) ^ 1] = 0;
        flowAdj[u].add(h << 1);
        flowAdj[v].add((h << 1) ^ 1);
    }

    static void dijkstra(int s) {
        Arrays.fill(pi, INF);
        pi[s] = 0;
        kk[s] = 0;
        cnt = 0;
        pq_add(s);
        while (cnt > 0) {
            int u = pq_remove_first();
            for (int h_ : flowAdj[u]) {
                if (cc[h_] == 0) continue;
                int h = h_ >> 1;
                int p = pi[u] + ((h_ & 1) == 0 ? cost_[h] : -cost_[h]);
                int v = u ^ uv[h];
                if (pi[v] == INF) {
                    pi[v] = p;
                    kk[v] = kk[u] + 1;
                    bb[v] = h_;
                    pq_add(v);
                } else if (p < pi[v] || (p == pi[v] && kk[u] + 1 < kk[v])) {
                    pi[v] = p;
                    kk[v] = kk[u] + 1;
                    bb[v] = h_;
                    pq_up(v);
                }
            }
        }
    }

    static void push(int s, int t) {
        int u = t;
        while (u != s) {
            int h_ = bb[u];
            int h = h_ >> 1;
            cc[h_]--;
            cc[h_ ^ 1]++;
            u ^= uv[h];
        }
    }

    static int edmonds_karp(int s, int t) {
        System.arraycopy(cost, 0, cost_, 0, m_);
        while (true) {
            dijkstra(s);
            if (pi[t] == INF) break;
            push(s, t);
            for (int h = 0; h < m_; h++) {
                int u = uu[h], v = vv[h];
                if (pi[u] != INF && pi[v] != INF)
                    cost_[h] += pi[u] - pi[v];
            }
        }
        int totalCost = 0;
        for (int h = 0; h < m_; h++)
            totalCost += cost[h] * cc[(h << 1) ^ 1];
        return totalCost;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        int[] people = new int[k];
        for (int i = 0; i < k; i++) {
            people[i] = sc.nextInt() - 1;
        }

        origAdj = new ArrayList[n];
        for (int i = 0; i < n; i++)
            origAdj[i] = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            origAdj[a].add(b);
            origAdj[b].add(a);
        }

        int t = n + k + 1;
        int n_ = n * t + 1;

        // Estimate maximum number of edges
        int maxLinks = m * (t - 1) * k + n * (t - 1) + k;
        int maxEdges = maxLinks * 2;
        uu = new int[maxEdges];
        vv = new int[maxEdges];
        uv = new int[maxEdges];
        cost = new int[maxEdges];
        cost_ = new int[maxEdges];
        cc = new int[maxEdges];

        flowAdj = new ArrayList[n_];
        for (int i = 0; i < n_; i++)
            flowAdj[i] = new ArrayList<>();

        m_ = 0;

        // Edges from movement
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                for (int j : origAdj[i]) {
                    int v = j * t + s + 1;
                    for (int x = 1; x <= k; x++) {
                        link(u, v, 1, c + (2 * x - 1) * d);
                    }
                }
            }
        }

        // Edges for staying
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                int v = u + 1;
                link(u, v, k, i == 0 ? 0 : c);
            }
        }

        // Source to each person's start
        for (int h = 0; h < k; h++) {
            link(n_ - 1, people[h] * t, 1, 0);
        }

        // Dijkstra arrays
        pi = new int[n_];
        kk = new int[n_];
        bb = new int[n_];
        pq = new int[n_ + 1];
        iq = new int[n_];

        int source = n_ - 1;
        int sink = 0 * t + t - 1;
        int result = edmonds_karp(source, sink);
        System.out.println(result);
    }
}
